          if (PLAYER_APPRENTICE.questionsAnswered >= NUM_WHICH_MON_QUESTIONS)
              return;
          strings[1] = gSpeciesNames[gApprenticeQuestionData.altSpeciesId];
          strings[0] = gSpeciesNames[gApprenticeQuestionData.speciesId];
